// === PARSE GOOGLE SHEETS + BUILD AI CONTEXT ===
const webhookData = $('Chat Webhook').first().json;
const body = webhookData.body || {};
const userMessage = body.message || '';
const sessionId = body.sessionId || 'default';
const dashboardState = body.state || {};

// Parse gviz response
const raw = String($input.first().json.data || '');
let alerts = [];
try {
  const match = raw.match(/google\.visualization\.Query\.setResponse\(([\s\S]*?)\);/);
  if (match) {
    const json = JSON.parse(match[1]);
    const rows = json.table.rows || [];
    const cols = json.table.cols.map(c => c.label);
    alerts = rows.map(row => {
      const obj = {};
      row.c.forEach((cell, i) => {
        obj[cols[i]] = cell ? (cell.v || cell.f || '') : '';
      });
      return obj;
    }).filter(a => a.Timestamp);
  }
} catch (e) { /* continue without data */ }

// Build context
let ctx = `=== GOOGLE SHEETS CANLI VERİLER (${alerts.length} kayıt) ===\n`;
if (alerts.length > 0) {
  const recent = alerts.slice(-20);
  ctx += 'Son 20 Alert:\n';
  recent.forEach(a => {
    ctx += `[${a.Timestamp}] ${a.Node} | ${a.Severity} | ${a.Anomaly} | Conf: ${a.Confidence} | ${a.Escalation} | Action: ${a['Healing Action'] || 'N/A'}\n`;
  });
  // Stats
  const sevCounts = {};
  const nodeCounts = {};
  alerts.forEach(a => {
    sevCounts[a.Severity] = (sevCounts[a.Severity] || 0) + 1;
    nodeCounts[a.Node] = (nodeCounts[a.Node] || 0) + 1;
  });
  const auto = alerts.filter(a => a.Escalation === 'AUTONOMOUS').length;
  const human = alerts.filter(a => a.Escalation === 'HUMAN_REVIEW').length;
  const esc = alerts.filter(a => a.Escalation === 'ESCALATED').length;
  ctx += `\nSeverity: ${Object.entries(sevCounts).map(([k,v]) => k+':'+v).join(', ')}`;
  ctx += `\nNode Dağılımı: ${Object.entries(nodeCounts).map(([k,v]) => k+':'+v).join(', ')}`;
  ctx += `\nEscalation: Autonomous:${auto}, Human Review:${human}, Escalated:${esc}`;
}

// Dashboard state
if (dashboardState.healthScores) {
  ctx += '\n\n=== DASHBOARD CANLI DURUM ===';
  Object.entries(dashboardState.healthScores).forEach(([id, score]) => {
    const s = score >= 80 ? 'Healthy' : score >= 50 ? 'Warning' : 'Critical';
    ctx += `\nNode #${id}: ${score}/100 (${s})`;
  });
}

return [{ json: { userMessage, sessionId, sheetsContext: ctx, alertCount: alerts.length } }];

// Format AI response for dashboard
const response = $input.first().json;
let reply = 'Üzgünüm, şu an yanıt üretemiyorum.';

try {
  if (response.choices && response.choices[0]) {
    reply = response.choices[0].message.content;
  }
} catch (e) {
  reply = 'Bir hata oluştu: ' + e.message;
}

return [{
  json: {
    output: reply,
    source: 'n8n-ai-agent',
    model: 'llama-3.3-70b-versatile',
    alertsUsed: $('Build AI Context').first().json.alertCount,
    timestamp: new Date().toISOString()
  }
}];
